  { g: 'Blue blobs', key: 'blueEat', label: 'Eating time', min: 0.2, max: 4, step: 0.1, fmt: (v) => `${v.toFixed(1)}s`, cls: 'blue' },
  { g: 'Red blobs', key: 'redUse', label: 'Energy use', min: 0.3, max: 2.5, step: 0.05, fmt: (v) => `×${v.toFixed(2)}`, cls: 'red' },
