import { Sim, BASE } from '/private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.3KObLy/app/src/sim.js';
const T=2400;
function run(o,seed){
  const s=new Sim({...BASE,worldSize:24,trees:9,blues:20,reds:3,...o,seed});
  const b=[],r=[];
  while(s.t<T){s.step(0.05); if(Math.abs(s.t%10)<0.025){b.push(s.blues.length);r.push(s.reds.length);}}
  const tail=(a)=>a.slice(60);
  const cv=(a)=>{const m=a.reduce((x,y)=>x+y,0)/a.length;const v=a.reduce((x,y)=>x+(y-m)**2,0)/a.length;return [m,Math.sqrt(v)/(m||1)]};
  // count red peaks (smoothed)
  const sm=(a)=>a.map((_,i)=>{let s=0,n=0;for(let k=-3;k<=3;k++){if(a[i+k]!=null){s+=a[i+k];n++}}return s/n});
  const peaks=(a)=>{const x=sm(tail(a));let c=0;for(let i=5;i<x.length-5;i++){if(x[i]>x[i-5]+1.5&&x[i]>x[i+5]+1.5&&x[i]>=x[i-1]&&x[i]>x[i+1])c++}return c};
  return {b:cv(tail(b)),r:cv(tail(r)),alive:r[r.length-1]>0&&b[b.length-1]>0,pk:peaks(r)};
}
for (const redCopy of [65,80]) for (const redUse of [0.5,0.8]) for (const redContact of [16,24]) for (const redVision of [10,14]) {
  const o={redCopy,redUse,redContact,redVision};
  const rs=[1,2,3].map(sd=>run(o,sd));
  console.log(JSON.stringify(o), rs.map(x=>`${x.alive?'ok':'DEAD'} b${x.b[0].toFixed(0)}cv${x.b[1].toFixed(2)} r${x.r[0].toFixed(1)}cv${x.r[1].toFixed(2)} pk${x.pk}`).join(' | '));
}
EOF
