:root {
  --bg: #f4efe1;
  --ink: #2c3a2a;
  --muted: #74806c;
  --card: #fffdf6;
  --line: #e4dcc6;
  --blue: #2f7bff;
  --red: #ee4347;
  --green: #5fb842;
  --accent: #4c9a3a;
  --radius: 18px;
  font-family: ui-rounded, 'SF Pro Rounded', 'Nunito', 'Segoe UI', system-ui, sans-serif;
  color: var(--ink);
  background: var(--bg);
}
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; background: radial-gradient(1200px 600px at 20% -10%, #fff8e0 0%, transparent 60%), var(--bg); }
button, input, select { font: inherit; color: inherit; }

.top {
  display: flex; align-items: center; gap: 18px; flex-wrap: wrap;
  padding: 12px 22px; position: sticky; top: 0; z-index: 20;
  background: rgba(244, 239, 225, 0.9); backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}
.top h1 { margin: 0; font-size: 22px; letter-spacing: -0.02em; margin-right: 8px; }
.transport { display: flex; gap: 8px; }
.btn {
  border: 1px solid var(--line); background: #fff; padding: 8px 14px; border-radius: 999px; cursor: pointer;
  font-weight: 650; font-size: 14px; box-shadow: 0 2px 0 var(--line); transition: transform .08s, box-shadow .08s, background .15s;
}
.btn:hover { background: #fbf6e6; }
.btn:active { transform: translateY(2px); box-shadow: none; }
.btn.primary { background: var(--accent); color: #fff; border-color: #3d7f2e; box-shadow: 0 2px 0 #3d7f2e; min-width: 84px; }
.btn.primary:hover { background: #56a843; }
.btn.small { padding: 5px 10px; font-size: 12px; }
.btn:focus-visible, input:focus-visible, .seg button:focus-visible { outline: 3px solid #9ecbff; outline-offset: 2px; }

.speed { display: inline-flex; background: #fff; border: 1px solid var(--line); border-radius: 999px; padding: 3px; gap: 2px; }
.speed button { border: 0; background: transparent; padding: 5px 10px; border-radius: 999px; cursor: pointer; font-weight: 650; font-size: 13px; color: var(--muted); }
.speed button.on { background: var(--ink); color: #fff; }
.clock { margin-left: auto; font-variant-numeric: tabular-nums; color: var(--muted); font-weight: 650; font-size: 14px; }

.layout { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 20px; padding: 20px 22px 40px; align-items: start; }
@media (max-width: 1050px) { .layout { grid-template-columns: 1fr; } .panel { position: static !important; max-height: none !important; } }

.stage {
  position: relative; height: clamp(440px, 64vh, 760px); border-radius: 26px; overflow: hidden;
  border: 1px solid #dccfae; box-shadow: 0 10px 30px -12px rgba(80, 60, 20, .35); background: #e8dbbb; touch-action: none;
}
#world { width: 100%; height: 100%; display: block; cursor: grab; }
#world.dragging { cursor: grabbing; }
#world.hovering { cursor: pointer; }
.hud { position: absolute; left: 14px; top: 14px; display: flex; gap: 8px; pointer-events: none; }
.chip {
  display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 999px;
  background: rgba(255, 253, 246, .92); border: 1px solid var(--line); font-size: 13px; font-weight: 600; color: var(--muted);
}
.chip b { color: var(--ink); font-size: 15px; font-variant-numeric: tabular-nums; min-width: 1.5ch; text-align: right; }
.chip i, .lg i { width: 11px; height: 11px; border-radius: 50%; display: inline-block; }
.chip.fruit i, .lg.fruit i { background: #8ed64d; }
.chip.blue i, .lg.blue i { background: var(--blue); }
.chip.red i, .lg.red i { background: var(--red); }
.cam-hint { position: absolute; left: 50%; bottom: 10px; transform: translateX(-50%); font-size: 12px; color: rgba(70, 55, 20, .6); pointer-events: none; white-space: nowrap; }
.cam-reset { position: absolute; right: 14px; top: 14px; }
.toast {
  position: absolute; left: 50%; top: 18px; transform: translateX(-50%); background: rgba(44, 58, 42, .92); color: #fff;
  padding: 8px 16px; border-radius: 999px; font-size: 13px; font-weight: 600; animation: pop .35s ease-out; pointer-events: none;
}
@keyframes pop { from { transform: translate(-50%, -10px) scale(.9); opacity: 0; } }

.inspector {
  position: absolute; left: 14px; bottom: 30px; width: 262px; padding: 14px 14px 12px; border-radius: 18px;
  background: rgba(255, 253, 246, .96); border: 1px solid var(--line); box-shadow: 0 8px 24px -10px rgba(60, 40, 10, .45); font-size: 13px;
}
.inspector header { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.inspector .dot { width: 14px; height: 14px; border-radius: 50%; }
.inspector .nm { font-weight: 750; font-size: 16px; }
.inspector .grp { color: var(--muted); font-size: 12px; }
.inspector .x { margin-left: auto; border: 0; background: transparent; cursor: pointer; font-size: 18px; color: var(--muted); line-height: 1; }
.inspector .act { padding: 4px 10px; border-radius: 999px; background: #f1ebd6; display: inline-block; font-weight: 650; margin-bottom: 8px; }
.bar { height: 8px; background: #eee6cf; border-radius: 99px; overflow: hidden; }
.bar > span { display: block; height: 100%; border-radius: 99px; transition: width .12s; }
.inspector .row { display: flex; justify-content: space-between; padding: 3px 0; color: var(--muted); }
.inspector .row b { color: var(--ink); font-variant-numeric: tabular-nums; }
.inspector .lbl { display: flex; justify-content: space-between; margin: 6px 0 3px; color: var(--muted); }

.charts { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-top: 18px; }
.card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px 14px; box-shadow: 0 3px 0 var(--line); min-width: 0; }
.card.wide { grid-column: 1 / -1; }
.card-head { display: flex; align-items: baseline; gap: 10px; margin-bottom: 8px; flex-wrap: wrap; }
.card h2 { margin: 0; font-size: 15px; }
.sub { color: var(--muted); font-size: 12px; }
.legend { display: flex; gap: 14px; margin-left: auto; font-size: 12px; color: var(--muted); font-weight: 600; flex-wrap: wrap; }
.legend.small { margin: 6px 0 0; gap: 10px; }
.lg { display: inline-flex; gap: 6px; align-items: center; }
.lg.dash i { background: transparent !important; border: 2px dashed currentColor; }
.lg.blue.dash { color: var(--blue); } .lg.red.dash { color: var(--red); }
.chart { width: 100%; height: 230px; display: block; }
.chart.tall { height: 270px; }
.mood { margin-left: auto; padding: 3px 10px; border-radius: 99px; font-size: 12px; font-weight: 700; background: #e3f2d6; color: #367a25; }
.mood.warn { background: #ffe9c9; color: #a3600c; }
.mood.bad { background: #ffdcdc; color: #a12c2c; }
.summary ul { margin: 0 0 10px; padding-left: 18px; font-size: 13.5px; line-height: 1.45; }
.summary li { margin-bottom: 5px; }
.summary dl { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 14px; margin: 0; font-size: 12px; }
.summary dl div { display: flex; justify-content: space-between; border-top: 1px dashed var(--line); padding-top: 4px; }
.summary dt { color: var(--muted); } .summary dd { margin: 0; font-weight: 700; font-variant-numeric: tabular-nums; }

.panel {
  position: sticky; top: 72px; max-height: calc(100vh - 92px); overflow-y: auto; padding-right: 4px;
  scrollbar-width: thin;
}
.pgroup, .sgroup {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px 14px 10px; margin-bottom: 12px; box-shadow: 0 3px 0 var(--line);
}
.pgroup h3, .sgroup h3 { margin: 0 0 8px; font-size: 13px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); display: flex; align-items: center; gap: 8px; }
.sgroup h3::before { content: ''; width: 10px; height: 10px; border-radius: 50%; background: var(--green); }
.sgroup.blue h3::before { background: var(--blue); } .sgroup.red h3::before { background: var(--red); } .sgroup.world h3::before { background: #c9a35a; }
.presets { display: flex; flex-wrap: wrap; gap: 6px; }
.presets button { border: 1px solid var(--line); background: #fff; border-radius: 999px; padding: 6px 11px; font-size: 12.5px; font-weight: 650; cursor: pointer; }
.presets button:hover { background: #fbf6e6; }
.presets button.on { background: var(--ink); color: #fff; border-color: var(--ink); }
.ctl { margin: 8px 0 10px; }
.ctl .top-row { display: flex; justify-content: space-between; font-size: 13px; font-weight: 600; margin-bottom: 2px; }
.ctl output { color: var(--muted); font-variant-numeric: tabular-nums; font-weight: 650; }
.ctl .tag { font-size: 10px; color: #a58a4a; background: #f7ecd0; border-radius: 99px; padding: 1px 6px; margin-left: 6px; font-weight: 700; }
input[type=range] { width: 100%; height: 22px; accent-color: var(--accent); margin: 0; cursor: pointer; }
