  }

  drawGround(g, R) {
    g.save();
    this.poly(g, this.ring(R - 0.05, 0)); g.clip();
    g.strokeStyle = 'rgba(255,255,255,.13)'; g.lineWidth = 2;
    for (const f of [0.33, 0.66]) { this.poly(g, this.ring(R * f, 0, 72)); g.stroke(); }
