    for (let i = 0; i < 6; i++) { const a = (i / 6) * TAU + 0.3; const p = this.proj(Math.cos(a) * R, Math.sin(a) * R), o = this.proj(0, 0); g.beginPath(); g.moveTo(o[0], o[1]); g.lineTo(p[0], p[1]); g.stroke(); }
