    for (let y = 0; y < this.h; y += 26) g.fillRect(0, y, this.w, 1);
    g.globalAlpha = 1;
  }

  ring(R, z, n = 96) {
    const pts = [];
    for (let i = 0; i < n; i++) { const a = (i / n) * TAU; pts.push(this.proj(Math.cos(a) * R, Math.sin(a) * R, z)); }
