  pm = niceMax(pm * 1.08); fm = niceMax(fm);
  const X = (t) => L + (t / tEnd) * pw, YP = (v) => T + ph - (v / pm) * ph, YF = (v) => T + ph - (v / fm) * ph;
  g.font = '11px ui-rounded, system-ui, sans-serif'; g.fillStyle = MUTED; g.strokeStyle = GRID; g.lineWidth = 1;
  for (let i = 0; i <= 4; i++) {
